import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        String path = "/tmp/…/app.log";
        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorCountsByComponent = new HashMap<>();
        Set<String> uniqueErrorMessages = new TreeSet<>();
        Map<Integer, Integer> hourCounts = new HashMap<>();

        Pattern p = Pattern.compile("^\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2})):\\d{2}:\\d{2}\\] (\\w+) \\(([^)]+)\\) - (.*)$");

        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;
                Matcher m = p.matcher(line);
                if (!m.matches()) continue;
                String hourStr = m.group(2);
                String level = m.group(3);
                String component = m.group(4);
                String message = m.group(5);
                int hour = Integer.parseInt(hourStr);

                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);
                hourCounts.put(hour, hourCounts.getOrDefault(hour, 0) + 1);

                if ("ERROR".equals(level)) {
                    errorCountsByComponent.put(component, errorCountsByComponent.getOrDefault(component, 0) + 1);
                    uniqueErrorMessages.add(message);
                }
            }
        } catch (IOException e) {
            // If file missing, continue with empty data
        }

        String mostErrorComponent = "";
        int mostErrorCount = 0;
        for (Map.Entry<String, Integer> e : errorCountsByComponent.entrySet()) {
            if (e.getValue() > mostErrorCount || (e.getValue() == mostErrorCount && e.getKey().compareTo(mostErrorComponent) < 0)) {
                mostErrorCount = e.getValue();
                mostErrorComponent = e.getKey();
            }
        }
        if (mostErrorComponent.isEmpty()) {
            mostErrorComponent = "None";
            mostErrorCount = 0;
        }

        int busiestHour = 0;
        int busiestCount = -1;
        for (Map.Entry<Integer, Integer> e : hourCounts.entrySet()) {
            int h = e.getKey();
            int c = e.getValue();
            if (c > busiestCount || (c == busiestCount && h < busiestHour)) {
                busiestCount = c;
                busiestHour = h;
            }
        }
        if (busiestCount < 0) {
            busiestCount = 0;
            busiestHour = 0;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Log Analysis ===\n\n");
        sb.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> e : levelCounts.entrySet()) {
            sb.append("  ").append(e.getKey()).append(": ").append(e.getValue()).append("\n");
        }
        sb.append("\n");
        sb.append("Component with Most Errors: ").append(mostErrorComponent).append(" (").append(mostErrorCount).append(" errors)\n\n");
        sb.append("Unique Error Messages:\n");
        for (String msg : uniqueErrorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");
        sb.append("Busiest Hour: ").append(String.format("%02d:00", busiestHour)).append(" (").append(busiestCount).append(" entries)");
        System.out.print(sb.toString());
    }
}

