import * as http from 'http';
import { URL } from 'url';

interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  stock: number;
}

function fetchProducts(): Promise<Product[]> {
  const url = new URL('http://127.0.0.1:18924/api/products');
  return new Promise((resolve, reject) => {
    const req = http.get(
      {
        hostname: url.hostname,
        port: Number(url.port),
        path: url.pathname,
        timeout: 5000,
      },
      (res) => {
        let data = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => (data += chunk));
        res.on('end', () => {
          try {
            const json = JSON.parse(data);
            resolve(Array.isArray(json) ? json as Product[] : []);
          } catch (e) {
            reject(e);
          }
        });
      }
    );
    req.on('error', reject);
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Request timeout'));
    });
  });
}

async function main() {
  try {
    const products = await fetchProducts();
    const filtered = products
      .filter(p => p.price > 50)
      .sort((a, b) => a.name.localeCompare(b.name));

