use std::collections::HashMap;
use std::fs;

fn format_int_commas(mut n: i64) -> String {
    let negative = n < 0;
    if negative {
        n = -n;
    }
    let s = n.to_string();
    let mut chars: Vec<char> = s.chars().rev().collect();
    let mut out = String::new();
    for (i, c) in chars.iter().enumerate() {
        if i > 0 && i % 3 == 0 {
            out.push(',');
        }
        out.push(*c);
    }
    let out: String = out.chars().rev().collect();
    if negative {
        format!("-{}", out)
    } else {
        out
    }
}

fn format_avg(sum: i64, count: usize) -> String {
    let count_i64 = count as i64;
    let cents = (sum * 100 + count_i64 / 2) / count_i64;
    let int_part = cents / 100;
    let frac_part = (cents % 100).abs();
    format!("{}.{:02}", format_int_commas(int_part), frac_part)
}

fn main() {
    let path = "/tmp/…/employees.csv";
    let content = fs::read_to_string(path).expect("Failed to read CSV");
    let mut dept_sum: HashMap<String, i64> = HashMap::new();
    let mut dept_cnt: HashMap<String, usize> = HashMap::new();
    let mut total_budget: i64 = 0;
    let mut highest_salary: i64 = i64::MIN;
    let mut highest_name = String::new();

    for (i, line) in content.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        if i == 0 {
            continue; // header
        }
        let parts: Vec<&str> = line.split(',').collect();
        if parts.len() < 6 {
            continue;
        }
        let name = parts[1].to_string();
        let department = parts[2].to_string();
        let salary: i64 = parts[3].parse().unwrap_or(0);

        *dept_sum.entry(department.clone()).or_insert(0) += salary;
        *dept_cnt.entry(department.clone()).or_insert(0) += 1;

        total_budget += salary;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }
    }

    let mut depts: Vec<String> = dept_sum.keys().cloned().collect();
    depts.sort();

