    println!("Departments with >2 employees:");
    let mut big_depts: Vec<(String, usize)> = dept_cnt
        .iter()
        .filter_map(|(d, c)| if *c > 2 { Some((d.clone(), *c)) } else { None })
        .collect();
    big_depts.sort_by(|a, b| a.0.cmp(&b.0));
    for (dept, cnt) in big_depts {
        println!("  {} ({} employees)", dept, cnt);
    }
    println!();
    println!("Total Budget: ${}", format_int_commas(total_budget));
}

