    if start in dist:
        dist[start] = 0
    else:
        # ensure start exists
        dist[start] = 0
        adj[start] = []

    heap = [(0, start)]
    visited = set()

    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        for v, w in adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(heap, (nd, v))

    # ensure all nodes have entry
    all_nodes = sorted(set(nodes) | {start})
    print("=== Shortest Paths from A ===")
    print()
    for node in all_nodes:
        d = dist.get(node, float("inf"))
        if d == float("inf"):
            d_str = "inf"
        else:
            # print as int if integer
            if isinstance(d, float) and d.is_integer():
                d_str = str(int(d))
            else:
                d_str = str(d)
        print(f"A -> {node}: {d_str}")

