public class Main {
    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18924/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = in.readLine()) != null) {
            sb.append(line);
        }
        in.close();
        String json = sb.toString();

        List<Product> products = new ArrayList<>();
        Pattern objPat = Pattern.compile("\\{[^}]*\\}");
        Matcher mObj = objPat.matcher(json);
        Pattern namePat = Pattern.compile("\"name\"\\s*:\\s*\"([^\"]+)\"");
        Pattern pricePat = Pattern.compile("\"price\"\\s*:\\s*([0-9]+(?:\\.[0-9]+)?)");
        while (mObj.find()) {
            String obj = mObj.group();
            Matcher mn = namePat.matcher(obj);
            Matcher mp = pricePat.matcher(obj);
            if (mn.find() && mp.find()) {
                String name = mn.group(1);
                double price = Double.parseDouble(mp.group(1));
                if (price > 50.00) {
                    products.add(new Product(name, price));
                }
            }
        }
        products.sort(Comparator.comparing(p -> p.name));

        System.out.println("=== Filtered Products (price > $50.00) ===");
