            System.out.println();
        }
        System.out.println("Count: " + products.size());
        double total = 0;
        for (Product p : products) total += p.price;
        System.out.printf("Total: $%.2f%n", total);
    }

    static class Product {
        String name;
        double price;
        Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }
}

