#define MAX_LINE 1024
#define MAX_NAME 256

typedef struct {
    char name[MAX_NAME];
    char dept[MAX_NAME];
    long long salary;
} Emp;

typedef struct {
    char name[MAX_NAME];
    long long sum;
    int count;
} Dept;

static void format_ll_commas(long long v, char *out) {
    char tmp[64];
    int len = sprintf(tmp, "%lld", v);
    int neg = 0;
    if (tmp[0] == '-') { neg = 1; }
    int i = len - 1 - neg;
    int j = 0;
    int cnt = 0;
    char rev[64];
    while (i >= 0) {
        rev[j++] = tmp[i--];
        cnt++;
        if (cnt == 3 && i >= 0) {
            rev[j++] = ',';
            cnt = 0;
        }
    }
    rev[j] = '\0';
    if (neg) {
        out[0] = '-';
        for (int k = 0; k < j; k++) out[k+1] = rev[j-1-k];
        out[j+1] = '\0';
    } else {
        for (int k = 0; k < j; k++) out[k] = rev[j-1-k];
        out[j] = '\0';
    }
}

static int dept_cmp(const void *a, const void *b) {
    const Dept *da = (const Dept *)a;
    const Dept *db = (const Dept *)b;
    return strcmp(da->name, db->name);
}

int main(void) {
    const char *path = "/tmp/…/employees.csv";
    FILE *f = fopen(path, "r");
    if (!f) return 1;

    Emp *emps = NULL;
    size_t emp_cap = 0, emp_n = 0;
    Dept *depts = NULL;
    size_t dept_cap = 0, dept_n = 0;

    long long total_budget = 0;
    long long highest_salary = -1;
    char highest_name[MAX_NAME] = "";

    char line[MAX_LINE];
    int first = 1;
    while (fgets(line, sizeof line, f)) {
        if (line[0] == '\n' || line[0] == '\r') continue;
        if (first) { first = 0; continue; } /* header */

        char *saveptr;
        char *tok = strtok_r(line, ",", &saveptr);
        if (!tok) continue;
        char *emp_id = tok;
        tok = strtok_r(NULL, ",", &saveptr);
        if (!tok) continue;
        char name[MAX_NAME];
        strncpy(name, tok, MAX_NAME-1);
        name[MAX_NAME-1] = '\0';
        tok = strtok_r(NULL, ",", &saveptr);
        if (!tok) continue;
        char dept[MAX_NAME];
        strncpy(dept, tok, MAX_NAME-1);
        dept[MAX_NAME-1] = '\0';
        tok = strtok_r(NULL, ",", &saveptr);
        if (!tok) continue;
        long long salary = strtoll(tok, NULL, 10);

        if (emp_n >= emp_cap) {
            emp_cap = emp_cap ? emp_cap*2 : 256;
            emps = realloc(emps, emp_cap * sizeof(Emp));
        }
        strncpy(emps[emp_n].name, name, MAX_NAME);
        strncpy(emps[emp_n].dept, dept, MAX_NAME);
        emps[emp_n].salary = salary;
        emp_n++;

        total_budget += salary;
        if (salary > highest_salary) {
            highest_salary = salary;
            strncpy(highest_name, name, MAX_NAME);
        }

        /* dept aggregation */
        int found = -1;
        for (size_t i = 0; i < dept_n; i++) {
            if (strcmp(depts[i].name, dept) == 0) { found = (int)i; break; }
        }
        if (found >= 0) {
            depts[found].sum += salary;
            depts[found].count += 1;
        } else {
            if (dept_n >= dept_cap) {
                dept_cap = dept_cap ? dept_cap*2 : 64;
                depts = realloc(depts, dept_cap * sizeof(Dept));
            }
            strncpy(depts[dept_n].name, dept, MAX_NAME);
            depts[dept_n].sum = salary;
            depts[dept_n].count = 1;
            dept_n++;
        }
    }
    fclose(f);

    if (dept_n > 0) qsort(depts, dept_n, sizeof(Dept), dept_cmp);

    printf("=== Salary Report ===\n\n");
    printf("Average Salary by Department:\n");
    for (size_t i = 0; i < dept_n; i++) {
        __int128 tmp = (__int128)depts[i].sum * 100;
        long long avg_cents = (long long)((tmp + depts[i].count/2) / depts[i].count);
        long long int_part = avg_cents / 100;
        long long frac = avg_cents % 100;
        if (frac < 0) frac = -frac;
        char intbuf[64];
        format_ll_commas(int_part, intbuf);
        printf("  %s: $%s.%02lld\n", depts[i].name, intbuf, frac);
    }
    printf("\n");
    char hi_buf[64];
    format_ll_commas(highest_salary, hi_buf);
    printf("Highest Paid: %s ($%s)\n\n", highest_name, hi_buf);
    printf("Departments with >2 employees:\n");
    for (size_t i = 0; i < dept_n; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");
    char tot_buf[64];
    format_ll_commas(total_budget, tot_buf);
    printf("Total Budget: $%s\n", tot_buf);

    free(emps);
    free(depts);
    return 0;
}

