let path = "/tmp/…/graph.json"
let data = try! Data(contentsOf: URL(fileURLWithPath: path))
let graph = try! JSONDecoder().decode(GraphData.self, from: data)

var adjacency: [String: [(String, Int)]] = [:]
for node in graph.nodes {
    adjacency[node] = []
}
for e in graph.edges {
    adjacency[e.from, default: []].append((e.to, e.weight))
    adjacency[e.to, default: []].append((e.from, e.weight))
}

let source = "A"
var dist: [String: Int] = [:]
for node in graph.nodes {
    dist[node] = Int.max
}
if dist.keys.contains(source) {
    dist[source] = 0
}
var unvisited = Set(graph.nodes)

while !unvisited.isEmpty {
    let u = unvisited.min { (dist[$0] ?? Int.max) < (dist[$1] ?? Int.max) }!
    unvisited.remove(u)
    let du = dist[u] ?? Int.max
    if du == Int.max { continue }
    guard let neighbors = adjacency[u] else { continue }
    for (v, w) in neighbors {
        if let dv = dist[v], du + w < dv {
            dist[v] = du + w
        }
    }
}

