import * as fs from 'fs';

type Edge = { from: string; to: string; weight: number };
type Graph = { nodes: string[]; edges: Edge[] };

const FILE_PATH = '/tmp/…/graph.json';
const raw = fs.readFileSync(FILE_PATH, 'utf-8');
const graph: Graph = JSON.parse(raw);

const adj = new Map<string, Array<{ to: string; weight: number }>>();
for (const n of graph.nodes) {
  adj.set(n, []);
}
for (const e of graph.edges) {
  if (!adj.has(e.from)) adj.set(e.from, []);
  if (!adj.has(e.to)) adj.set(e.to, []);
  adj.get(e.from)!.push({ to: e.to, weight: e.weight });
  adj.get(e.to)!.push({ to: e.from, weight: e.weight });
}

const start = 'A';
const dist = new Map<string, number>();
const visited = new Set<string>();
for (const n of graph.nodes) {
  dist.set(n, Infinity);
}
dist.set(start, 0);

while (visited.size < graph.nodes.length) {
  let u: string | null = null;
  let best = Infinity;
  for (const n of graph.nodes) {
    if (!visited.has(n)) {
      const d = dist.get(n)!;
      if (d < best) {
        best = d;
        u = n;
      }
    }
  }
  if (u === null) break;
  visited.add(u);
  const neighbors = adj.get(u) ?? [];
  for (const { to, weight } of neighbors) {
    if (visited.has(to)) continue;
    const alt = dist.get(u)! + weight;
    if (alt < (dist.get(to) ?? Infinity)) {
      dist.set(to, alt);
    }
  }
}

console.log('=== Shortest Paths from A ===');
console.log('');
const sortedNodes = [...graph.nodes].sort();
for (const n of sortedNodes) {
  const d = dist.get(n);
  const outDist = d === Infinity ? 'Infinity' : d;
  console.log(`A -> ${n}: ${outDist}`);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct {
    char name[256];
    double price;
} Product;

int cmp_product(const void *a, const void *b) {
    const Product *pa = (const Product *)a;
    const Product *pb = (const Product *)b;
    return strcmp(pa->name, pb->name);
}

int main(void) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return 1;
    struct sockaddr_in serv;
    memset(&serv, 0, sizeof(serv));
    serv.sin_family = AF_INET;
    serv.sin_port = htons(18924);
    inet_pton(AF_INET, "127.0.0.1", &serv.sin_addr);
    if (connect(sock, (struct sockaddr *)&serv, sizeof(serv)) < 0) {
        close(sock);
        return 1;
    }
    const char *req = "GET /api/products HTTP/1.0\r\nHost: 127.0.0.1:18924\r\n\r\n";
    send(sock, req, strlen(req), 0);

    size_t bufsize = 8192;
    char *buf = malloc(bufsize);
    size_t len = 0;
    ssize_t n;
    while ((n = recv(sock, buf + len, bufsize - len - 1, 0)) > 0) {
        len += n;
        if (len >= bufsize - 1) {
            bufsize *= 2;
            char *nb = realloc(buf, bufsize);
            if (!nb) { free(buf); close(sock); return 1; }
            buf = nb;
        }
    }
    buf[len] = '\0';
    close(sock);

    char *body = strstr(buf, "\r\n\r\n");
    if (body) body += 4;
    else body = buf;

    Product *arr = NULL;
    size_t count = 0, cap = 0;

    char *p = body;
    while (*p) {
        char *obj = strchr(p, '{');
        if (!obj) break;
        char *name_key = strstr(obj, "\"name\"");
        if (!name_key) { p = obj + 1; continue; }
        char *colon = strchr(name_key, ':');
        if (!colon) { p = obj + 1; continue; }
        char *q1 = strchr(colon, '"');
        if (!q1) { p = obj + 1; continue; }
        char *q2 = strchr(q1 + 1, '"');
        if (!q2) { p = obj + 1; continue; }
        size_t nlen = q2 - q1 - 1;
        if (nlen >= 255) nlen = 255;
        char name_buf[256];
        memcpy(name_buf, q1 + 1, nlen);
        name_buf[nlen] = '\0';

        char *price_key = strstr(obj, "\"price\"");
        if (!price_key) { p = obj + 1; continue; }
        char *pcolon = strchr(price_key, ':');
        if (!pcolon) { p = obj + 1; continue; }
        char *ps = pcolon + 1;
        while (*ps && (*ps == ' ' || *ps == '\t')) ps++;
        char *pe = ps;
        while (*pe && (( *pe >= '0' && *pe <= '9') || *pe == '.' || *pe == '-' || *pe == '+' || *pe == 'e' || *pe == 'E')) pe++;
        if (ps == pe) { p = obj + 1; continue; }
        size_t plen = pe - ps;
        if (plen >= 63) plen = 63;
        char price_str[64];
        memcpy(price_str, ps, plen);
        price_str[plen] = '\0';
        double price = strtod(price_str, NULL);
        if (price > 50.0) {
            if (count == cap) {
                cap = cap ? cap * 2 : 16;
                Product *na = realloc(arr, cap * sizeof(Product));
                if (!na) { free(arr); free(buf); return 1; }
                arr = na;
            }
            strncpy(arr[count].name, name_buf, 255);
            arr[count].name[255] = '\0';
            arr[count].price = price;
            count++;
        }
        p = obj + 1;
    }

    if (count > 1) qsort(arr, count, sizeof(Product), cmp_product);

    printf("=== Filtered Products (price > $50.00) ===\n\n");
    double total = 0.0;
    for (size_t i = 0; i < count; i++) {
        printf("%s: $%.2f\n", arr[i].name, arr[i].price);
        total += arr[i].price;
    }
    printf("\n");
    printf("Count: %zu\n", count);
    printf("Total: $%.2f\n", total);

    free(arr);
    free(buf);
    return 0;
}

use std::collections::{BTreeSet, HashMap};
use std::fs;

fn main() {
    let path = "/tmp/…/app.log";
    let content = fs::read_to_string(path).unwrap_or_default();

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut error_counts_by_component: HashMap<String, usize> = HashMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: HashMap<u32, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || !line.starts_with('[') {
            continue;
        }
        let close_bracket = match line.find(']') {
            Some(i) => i,
            None => continue,
        };
        let timestamp = &line[1..close_bracket];
        if let Some(space_idx) = timestamp.find(' ') {
            let time_part = &timestamp[space_idx + 1..];
            if time_part.len() >= 2 {
                if let Ok(h) = time_part[0..2].parse::<u32>() {
                    *hour_counts.entry(h).or_insert(0) += 1;
                }
            }
        }

        let after = line[close_bracket + 1..].trim_start();
        let level_end = after.find(' ').unwrap_or(after.len());
        let level = &after[..level_end];
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        let rest = after[level_end..].trim_start();
        if let Some(open) = rest.find('(') {
            let close_rel = match rest[open..].find(')') {
                Some(i) => open + i,
                None => continue,
            };
            let component = &rest[open + 1..close_rel];
            let after_comp = rest[close_rel + 1..].trim_start();
            let message = if after_comp.starts_with('-') {
                after_comp[1..].trim_start()
            } else {
                after_comp
            };
            if level == "ERROR" {
                *error_counts_by_component.entry(component.to_string()).or_insert(0) += 1;
                error_messages.insert(message.to_string());
            }
        }
    }

    let mut levels: Vec<(String, usize)> = level_counts.into_iter().collect();
    levels.sort_by(|a, b| a.0.cmp(&b.0));

    let (most_err_component, most_err_count) = error_counts_by_component
        .into_iter()
        .max_by(|a, b| a.1.cmp(&b.1))
        .unwrap_or((String::new(), 0));

    let (busiest_hour, busiest_count) = hour_counts
        .into_iter()
        .max_by(|a, b| a.1.cmp(&b.1))
        .unwrap_or((0, 0));

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (lvl, cnt) in &levels {
        println!("  {}: {}", lvl, cnt);
    }
    println!();
    println!("Component with Most Errors: {} ({} errors)", most_err_component, most_err_count);
    println!();
    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    static class Edge {
        String to;
        int weight;
        Edge(String to, int weight) { this.to = to; this.weight = weight; }
    }

    static class NodeDist implements Comparable<NodeDist> {
        String node;
        long dist;
        NodeDist(String node, long dist) { this.node = node; this.dist = dist; }
        public int compareTo(NodeDist o) { return Long.compare(this.dist, o.dist); }
    }

    public static void main(String[] args) throws IOException {
        String path = "/tmp/…/graph.json";
        String content = Files.readString(Path.of(path));

        List<String> nodes = new ArrayList<>();
        Pattern nodesPat = Pattern.compile("\"nodes\"\\s*:\\s*\\[(.*?)]");
        Matcher m = nodesPat.matcher(content);
        if (m.find()) {
            String inside = m.group(1);
            Pattern itemPat = Pattern.compile("\"([^\"]+)\"");
            Matcher im = itemPat.matcher(inside);
            while (im.find()) nodes.add(im.group(1));
        }

        Map<String, List<Edge>> adj = new HashMap<>();
        for (String n : nodes) adj.put(n, new ArrayList<>());

        Pattern edgePat = Pattern.compile("\\{\\s*\"from\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"to\"\\s*:\\s*\"([^\"]+)\"\\s*,\\s*\"weight\"\\s*:\\s*(\\d+)\\s*\\}");
        Matcher em = edgePat.matcher(content);
        while (em.find()) {
            String from = em.group(1);
            String to = em.group(2);
            int w = Integer.parseInt(em.group(3));
            adj.computeIfAbsent(from, k -> new ArrayList<>()).add(new Edge(to, w));
            adj.computeIfAbsent(to, k -> new ArrayList<>()).add(new Edge(from, w));
        }

        String source = "A";
        Map<String, Long> dist = new HashMap<>();
        for (String n : nodes) dist.put(n, Long.MAX_VALUE);
        if (adj.containsKey(source)) dist.put(source, 0L);

        PriorityQueue<NodeDist> pq = new PriorityQueue<>();
        pq.add(new NodeDist(source, 0));

        Set<String> visited = new HashSet<>();
        while (!pq.isEmpty()) {
            NodeDist cur = pq.poll();
            if (visited.contains(cur.node)) continue;
            visited.add(cur.node);
            long d = cur.dist;
            for (Edge e : adj.getOrDefault(cur.node, Collections.emptyList())) {
                long nd = d + e.weight;
