fn parse_nodes(content: &str) -> Vec<String> {
    if let Some(nodes_pos) = content.find("\"nodes\"") {
        let after = &content[nodes_pos..];
        if let Some(bracket_start) = after.find('[') {
            if let Some(bracket_end) = after[bracket_start..].find(']') {
                let inner = &after[bracket_start + 1..bracket_start + bracket_end];
                let mut nodes = Vec::new();
                for part in inner.split(',') {
                    let p = part.trim().trim_matches('"');
                    if !p.is_empty() {
                        nodes.push(p.to_string());
                    }
                }
                return nodes;
            }
        }
    }
    Vec::new()
}

fn parse_edges(content: &str) -> Vec<(String, String, u32)> {
    let mut edges = Vec::new();
    if let Some(edges_pos) = content.find("\"edges\"") {
        let after = &content[edges_pos..];
        if let Some(bracket_start) = after.find('[') {
            // find matching ]
            let mut depth = 0;
            let mut end = None;
            for (i, ch) in after[bracket_start..].char_indices() {
                if ch == '[' { depth += 1; }
                if ch == ']' { depth -= 1; if depth == 0 { end = Some(bracket_start + i); break; } }
            }
            if let Some(e_end) = end {
                let edges_str = &after[bracket_start + 1..e_end];
                let mut i = 0;
                let bytes = edges_str.as_bytes();
                while i < bytes.len() {
                    // find "from"
                    if let Some(from_idx) = edges_str[i..].find("\"from\"") {
                        let mut pos = i + from_idx;
                        // skip to value
                        if let Some(colon) = edges_str[pos..].find(':') {
                            pos += colon + 1;
                            if let Some(q1) = edges_str[pos..].find('"') {
                                pos += q1 + 1;
                                if let Some(q2) = edges_str[pos..].find('"') {
                                    let from = &edges_str[pos..pos + q2];
                                    pos += q2 + 1;
                                    // find "to"
                                    if let Some(to_idx) = edges_str[pos..].find("\"to\"") {
                                        let mut pos2 = pos + to_idx;
                                        if let Some(colon2) = edges_str[pos2..].find(':') {
                                            pos2 += colon2 + 1;
                                            if let Some(q1b) = edges_str[pos2..].find('"') {
                                                pos2 += q1b + 1;
                                                if let Some(q2b) = edges_str[pos2..].find('"') {
                                                    let to = &edges_str[pos2..pos2 + q2b];
                                                    pos2 += q2b + 1;
                                                    // find weight
                                                    if let Some(w_idx) = edges_str[pos2..].find("\"weight\"") {
                                                        let mut pos3 = pos2 + w_idx;
                                                        if let Some(colon3) = edges_str[pos3..].find(':') {
                                                            pos3 += colon3 + 1;
                                                            let mut num_start = pos3;
                                                            while num_start < edges_str.len() && edges_str.as_bytes()[num_start].is_ascii_whitespace() {
                                                                num_start += 1;
                                                            }
                                                            let mut num_end = num_start;
                                                            while num_end < edges_str.len() && edges_str.as_bytes()[num_end].is_ascii_digit() {
                                                                num_end += 1;
                                                            }
                                                            if num_end > num_start {
                                                                let w_str = &edges_str[num_start..num_end];
                                                                if let Ok(w) = w_str.parse::<u32>() {
                                                                    edges.push((from.to_string(), to.to_string(), w));
                                                                }
                                                            }
                                                            i = num_end;
                                                            continue;
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    i += 1;
                }
            }
        }
    }
    edges
}

fn main() {
    let path = "/tmp/…/graph.json";
    let content = fs::read_to_string(path).expect("read file");
    let nodes = parse_nodes(&content);
    let edges_raw = parse_edges(&content);

    let mut adj: HashMap<String, Vec<(String, u32)>> = HashMap::new();
    for n in &nodes {
        adj.entry(n.clone()).or_insert_with(Vec::new);
    }
    for (u, v, w) in edges_raw {
        adj.entry(u.clone()).or_insert_with(Vec::new).push((v.clone(), w));
        adj.entry(v.clone()).or_insert_with(Vec::new).push((u.clone(), w));
    }

    let start = "A".to_string();
    let mut dist: HashMap<String, u64> = HashMap::new();
    for n in &nodes {
        dist.insert(n.clone(), u64::MAX);
    }
    if dist.contains_key(&start) {
        dist.insert(start.clone(), 0);
    }

    let mut heap = BinaryHeap::new();
    heap.push((Reverse(0u64), start.clone()));

    while let Some((Reverse(d), u)) = heap.pop() {
        if d != *dist.get(&u).unwrap_or(&u64::MAX) {
            continue;
        }
        if let Some(neigh) = adj.get(&u) {
            for (v, w) in neigh {
                let nd = d + *w as u64;
                let entry = dist.entry(v.clone()).or_insert(u64::MAX);
                if nd < *entry {
                    *entry = nd;
                    heap.push((Reverse(nd), v.clone()));
                }
            }
        }
    }

    println!("=== Shortest Paths from A ===");
    println!("");
    let mut sorted_nodes = nodes.clone();
    sorted_nodes.sort();
    for n in sorted_nodes {
        let d = dist.get(&n).copied().unwrap_or(u64::MAX);
        if d == u64::MAX {
            println!("A -> {}: unreachable", n);
        } else {
            println!("A -> {}: {}", n, d);
        }
    }
}

