        .find(|c: char| !c.is_ascii_digit() && c != '.' && c != '-' && c != 'e' && c != 'E' && c != '+')
        .unwrap_or(price_slice.len());
    let price_str = &price_slice[..price_end];
    let price: f64 = price_str.trim().parse().ok()?;

    Some((name, price))
}

