#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>
#include <limits.h>

typedef struct {
    char *rel;
    char *ext;
    long lines;
    long chars;
} FileEntry;

static FileEntry *entries = NULL;
static size_t n_entries = 0;
static size_t cap_entries = 0;
static long total_files = 0;
static long total_lines_all = 0;
static long total_chars_all = 0;

static void add_entry(const char *rel, const char *ext, long lines, long chars) {
    if (n_entries == cap_entries) {
        size_t newcap = cap_entries ? cap_entries * 2 : 1024;
        FileEntry *tmp = realloc(entries, newcap * sizeof(FileEntry));
        if (!tmp) exit(1);
        entries = tmp;
        cap_entries = newcap;
    }
    entries[n_entries].rel = strdup(rel);
    entries[n_entries].ext = strdup(ext);
    entries[n_entries].lines = lines;
    entries[n_entries].chars = chars;
    n_entries++;
    total_files++;
    total_lines_all += lines;
    total_chars_all += chars;
}

static const char *get_ext(const char *name) {
    const char *dot = strrchr(name, '.');
    if (dot && dot != name) {
        return dot;
    }
    return "";
}

static long count_lines_and_chars(const char *path, long *out_chars) {
    struct stat st;
    if (stat(path, &st) != 0) {
        *out_chars = 0;
        return 0;
    }
    long chars = st.st_size;
    *out_chars = chars;
    FILE *f = fopen(path, "rb");
    if (!f) return 0;
    long lines = 0;
    unsigned char buf[65536];
    size_t r;
    while ((r = fread(buf, 1, sizeof(buf), f)) > 0) {
        for (size_t i = 0; i < r; i++) {
            if (buf[i] == '\n') lines++;
        }
    }
    fclose(f);
    return lines;
}

static void walk_dir(const char *abs_path, const char *rel_prefix) {
    DIR *d = opendir(abs_path);
    if (!d) return;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        const char *name = de->d_name;
        if (strcmp(name, ".") == 0 || strcmp(name, "..") == 0) continue;

        char abs_child[PATH_MAX];
        snprintf(abs_child, sizeof(abs_child), "%s/%s", abs_path, name);

        char rel_child[PATH_MAX];
        if (rel_prefix[0] == '\0')
            snprintf(rel_child, sizeof(rel_child), "%s", name);
        else
            snprintf(rel_child, sizeof(rel_child), "%s/%s", rel_prefix, name);

        struct stat st;
        if (lstat(abs_child, &st) != 0) continue;
        if (S_ISLNK(st.st_mode)) continue;

        if (S_ISDIR(st.st_mode)) {
            walk_dir(abs_child, rel_child);
        } else if (S_ISREG(st.st_mode)) {
            const char *ext = get_ext(name);
            long chars;
            long lines = count_lines_and_chars(abs_child, &chars);
            add_entry(rel_child, ext, lines, chars);
        }
    }
    closedir(d);
}

static int cmp_entries(const void *a, const void *b) {
    const FileEntry *ea = (const FileEntry *)a;
    const FileEntry *eb = (const FileEntry *)b;
    int c = strcmp(ea->ext, eb->ext);
    if (c != 0) return c;
    return strcmp(ea->rel, eb->rel);
}

int main(void) {
    const char *base = "/tmp/…/project_tree";
    walk_dir(base, "");
    if (n_entries > 0) qsort(entries, n_entries, sizeof(FileEntry), cmp_entries);

    printf("=== File Tree Analysis ===\n\n");
    size_t i = 0;
    while (i < n_entries) {
        size_t j = i;
        long group_lines = 0;
        long group_chars = 0;
        while (j < n_entries && strcmp(entries[j].ext, entries[i].ext) == 0) {
            group_lines += entries[j].lines;
            group_chars += entries[j].chars;
            j++;
        }
        size_t group_count = j - i;
        printf("Extension: %s\n", entries[i].ext);
        printf("  Files: %zu\n", group_count);
        printf("  Total Lines: %ld\n", group_lines);
        printf("  Total Characters: %ld\n", group_chars);
        for (size_t k = i; k < j; k++) {
            printf("    %s: %ld lines, %ld chars\n", entries[k].rel, entries[k].lines, entries[k].chars);
        }
        i = j;
    }
    if (n_entries > 0) printf("\n");
    printf("Total: %ld files, %ld lines, %ld characters\n", total_files, total_lines_all, total_chars_all);

    for (size_t k = 0; k < n_entries; k++) {
        free(entries[k].rel);
        free(entries[k].ext);
    }
    free(entries);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

char *run_cmd(const char *cmd) {
    FILE *pipe = popen(cmd, "r");
    if (!pipe) return NULL;
    size_t cap = 4096;
    size_t len = 0;
    char *buf = malloc(cap);
    if (!buf) { pclose(pipe); return NULL; }
    char tmp[256];
    while (fgets(tmp, sizeof tmp, pipe)) {
        size_t tlen = strlen(tmp);
        if (len + tlen >= cap) {
            cap *= 2;
            char *nb = realloc(buf, cap);
            if (!nb) { free(buf); pclose(pipe); return NULL; }
            buf = nb;
        }
        memcpy(buf + len, tmp, tlen);
        len += tlen;
    }
    pclose(pipe);
    buf[len] = '\0';
    while (len > 0 && isspace((unsigned char)buf[len - 1])) {
        buf[--len] = '\0';
    }
    return buf;
}

int main(void) {
    char *hostname = run_cmd("hostname");
    char *os = run_cmd("uname -s");
    char *arch = run_cmd("uname -m");
    char *user = run_cmd("whoami");

    if (!hostname) hostname = strdup("");
    if (!os) os = strdup("");
    if (!arch) arch = strdup("");
    if (!user) user = strdup("");

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname);
    printf("  \"os\": \"%s\",\n", os);
    printf("  \"architecture\": \"%s\",\n", arch);
    printf("  \"username\": \"%s\"\n", user);
    printf("}\n");

    free(hostname);
    free(os);
    free(arch);
    free(user);
    return 0;
}

use std::process::Command;

fn get_output(cmd: &str, args: &[&str]) -> String {
    let output = Command::new(cmd).args(args).output().expect("command failed");
    String::from_utf8_lossy(&output.stdout).trim().to_string()
}

fn json_escape(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

