    int count;
} LevelEntry;

typedef struct {
    char name[256];
    int count;
} CompEntry;

int cmp_level(const void *a, const void *b) {
    return strcmp(((const LevelEntry*)a)->name, ((const LevelEntry*)b)->name);
}
int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char**)a, *(const char**)b);
}

int main(void) {
    const char *path = "/tmp/…/app.log";
    FILE *f = fopen(path, "r");
    if (!f) return 1;

    LevelEntry *levels = malloc(INIT_CAP * sizeof(LevelEntry));
    int levels_cap = INIT_CAP, levels_cnt = 0;
    CompEntry *comps = malloc(INIT_CAP * sizeof(CompEntry));
    int comps_cap = INIT_CAP, comps_cnt = 0;
    char **messages = malloc(INIT_CAP * sizeof(char*));
    int msgs_cap = INIT_CAP, msgs_cnt = 0;

    int hour_counts[24] = {0};

    char line[MAX_LINE];
    while (fgets(line, sizeof(line), f)) {
        int year, month, day, hour, minute, second;
        char level[64], component[256], message[4096];
        int scanned = sscanf(line,
            "[%d-%d-%d %d:%d:%d] %63s (%255[^)]) - %4095[^\n]",
            &year, &month, &day, &hour, &minute, &second,
            level, component, message);
        if (scanned < 9) continue;
        if (hour < 0 || hour > 23) hour = 0;
        hour_counts[hour]++;

        /* levels */
        int li;
        for (li = 0; li < levels_cnt; li++) if (strcmp(levels[li].name, level) == 0) break;
        if (li == levels_cnt) {
            if (levels_cnt == levels_cap) {
                levels_cap *= 2;
                levels = realloc(levels, levels_cap * sizeof(LevelEntry));
            }
            strncpy(levels[levels_cnt].name, level, 63);
            levels[levels_cnt].name[63] = '\0';
            levels[levels_cnt].count = 0;
            li = levels_cnt++;
        }
        levels[li].count++;

        if (strcmp(level, "ERROR") == 0) {
            /* component error count */
            int ci;
            for (ci = 0; ci < comps_cnt; ci++) if (strcmp(comps[ci].name, component) == 0) break;
            if (ci == comps_cnt) {
                if (comps_cnt == comps_cap) {
                    comps_cap *= 2;
                    comps = realloc(comps, comps_cap * sizeof(CompEntry));
                }
                strncpy(comps[comps_cnt].name, component, 255);
                comps[comps_cnt].name[255] = '\0';
                comps[comps_cnt].count = 0;
                ci = comps_cnt++;
            }
            comps[ci].count++;

            /* unique messages */
            if (msgs_cnt == msgs_cap) {
                msgs_cap *= 2;
                messages = realloc(messages, msgs_cap * sizeof(char*));
            }
            messages[msgs_cnt] = malloc(strlen(message) + 1);
            strcpy(messages[msgs_cnt], message);
            msgs_cnt++;
        }
    }
    fclose(f);

    qsort(levels, levels_cnt, sizeof(LevelEntry), cmp_level);

    char comp_best[256] = "";
    int comp_best_cnt = 0;
    for (int i = 0; i < comps_cnt; i++) {
        if (comps[i].count > comp_best_cnt) {
            comp_best_cnt = comps[i].count;
            strncpy(comp_best, comps[i].name, 255);
            comp_best[255] = '\0';
        }
    }
    if (comps_cnt == 0) strcpy(comp_best, "");

    int best_hour = 0;
    int best_hour_cnt = -1;
    for (int i = 0; i < 24; i++) {
        if (hour_counts[i] > best_hour_cnt) {
            best_hour_cnt = hour_counts[i];
            best_hour = i;
        }
    }
    if (best_hour_cnt < 0) best_hour_cnt = 0;

    /* unique messages sorted */
    qsort(messages, msgs_cnt, sizeof(char*), cmp_str);
    /* deduplicate for printing */
    int uniq_msgs_cnt = 0;
    char **uniq_msgs = malloc(msgs_cnt * sizeof(char*));
    for (int i = 0; i < msgs_cnt; i++) {
        if (i == 0 || strcmp(messages[i], messages[i-1]) != 0) {
            uniq_msgs[uniq_msgs_cnt++] = messages[i];
        } else {
            free(messages[i]);
        }
    }

    printf("=== Log Analysis ===\n\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < levels_cnt; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }
    printf("\n");
    printf("Component with Most Errors: %s (%d errors)\n", comp_best, comp_best_cnt);
    printf("\nUnique Error Messages:\n");
    for (int i = 0; i < uniq_msgs_cnt; i++) {
        printf("  - %s\n", uniq_msgs[i]);
    }
    printf("\nBusiest Hour: %02d:00 (%d entries)\n", best_hour, best_hour_cnt);

    free(levels);
    free(comps);
    for (int i = 0; i < uniq_msgs_cnt; i++) free(uniq_msgs[i]);
    free(uniq_msgs);
    free(messages);
    free(uniq_msgs);
    return 0;
}

