public class Main {
    public static void main(String[] args) {
        int[][] A = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        int[][] B = {{9, 8, 7}, {6, 5, 4}, {3, 2, 1}};
        int n = 3;
        int[][] C = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int sum = 0;
                for (int k = 0; k < n; k++) {
                    sum += A[i][k] * B[k][j];
                }
                C[i][j] = sum;
            }
        }

        int det = determinant3x3(C);

        System.out.println("=== Matrix Operations ===");
        System.out.println();
        System.out.println("Matrix A:");
        printMatrix(A);
        System.out.println();
        System.out.println("Matrix B:");
        printMatrix(B);
        System.out.println();
        System.out.println("A x B =");
        printMatrix(C);
        System.out.println();
        System.out.println("Determinant: " + det);
    }

    private static void printMatrix(int[][] m) {
        for (int i = 0; i < m.length; i++) {
            System.out.print("  ");
            for (int j = 0; j < m[i].length; j++) {
                System.out.printf("%4d", m[i][j]);
                if (j < m[i].length - 1) System.out.print(" ");
            }
            System.out.println();
        }
    }

    private static int determinant3x3(int[][] m) {
        int a = m[0][0], b = m[0][1], c = m[0][2];
        int d = m[1][0], e = m[1][1], f = m[1][2];
        int g = m[2][0], h = m[2][1], i = m[2][2];
        return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
    }
}

import * as fs from 'fs/promises';
import * as path from 'path';

const ROOT = '/tmp/…/project_tree';

type FileInfo = {
  relPath: string;
  lines: number;
  chars: number;
};

type ExtGroup = {
  files: FileInfo[];
  totalLines: number;
  totalChars: number;
};

async function walk(current: string, relBase: string): Promise<Map<string, ExtGroup>> {
  const map = new Map<string, ExtGroup>();
  const entries = await fs.readdir(current, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue;
    const fullPath = path.join(current, entry.name);
    const relPath = path.relative(ROOT, fullPath).split(path.sep).join('/');
    if (entry.isDirectory()) {
      const subMap = await walk(fullPath, relPath);
      for (const [ext, group] of subMap) {
        const existing = map.get(ext);
        if (existing) {
          existing.files.push(...group.files);
          existing.totalLines += group.totalLines;
          existing.totalChars += group.totalChars;
        } else {
          map.set(ext, group);
        }
      }
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name) || '';
      const stat = await fs.stat(fullPath);
      const chars = stat.size;
      const content = await fs.readFile(fullPath, 'utf8').catch(() => '');
      const lines = content.length === 0 ? 0 : content.split('\n').length;
      const info: FileInfo = { relPath, lines, chars };
      const group = map.get(ext) ?? { files: [], totalLines: 0, totalChars: 0 };
      group.files.push(info);
      group.totalLines += lines;
      group.totalChars += chars;
      map.set(ext, group);
    }
  }
  return map;
}

async function main() {
  const map = await walk(ROOT, '');
  const extensions = Array.from(map.keys()).sort();
  for (const g of map.values()) {
    g.files.sort((a, b) => a.relPath.localeCompare(b.relPath));
  }

  let totalFiles = 0;
  let totalLines = 0;
  let totalChars = 0;

  console.log('=== File Tree Analysis ===');
  console.log('');
  for (let i = 0; i < extensions.length; i++) {
    const ext = extensions[i];
    const group = map.get(ext)!;
    console.log(`Extension: ${ext}`);
    console.log(`  Files: ${group.files.length}`);
    console.log(`  Total Lines: ${group.totalLines}`);
    console.log(`  Total Characters: ${group.totalChars}`);
    for (const f of group.files) {
      console.log(`    ${f.relPath}: ${f.lines} lines, ${f.chars} chars`);
    }
    totalFiles += group.files.length;
    totalLines += group.totalLines;
    totalChars += group.totalChars;
  }
  console.log('');
  console.log(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);
}

