use std::collections::BTreeMap;
use std::fs::{self, File};
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};

struct FileInfo {
    rel_path: String,
    lines: usize,
    chars: u64,
}

fn walk(current: &Path, base: &Path, out: &mut Vec<(String, String, usize, u64)>) {
    if let Ok(entries) = fs::read_dir(current) {
        for entry in entries.flatten() {
            let path = entry.path();
            if let Ok(meta) = fs::symlink_metadata(&path) {
                if meta.file_type().is_symlink() {
                    continue;
                }
                if meta.is_dir() {
                    walk(&path, base, out);
                } else if meta.is_file() {
                    if let Ok(rel) = path.strip_prefix(base).and_then(|p| p.to_str().map(|s| s.replace("\\", "/"))) {
                        let ext = path.extension()
                            .and_then(|os| os.to_str())
                            .map(|s| format!(".{}", s))
                            .unwrap_or_default();
                        let chars = meta.len();
                        let lines = if let Ok(f) = File::open(&path) {
                            let reader = BufReader::new(f);
                            reader.lines().count()
                        } else {
                            0
                        };
                        out.push((ext, rel, lines, chars));
                    }
                }
            }
        }
    }
}

fn main() {
    let base_path = PathBuf::from("/tmp/…/project_tree");
    let mut files: Vec<(String, String, usize, u64)> = Vec::new();
    walk(&base_path, &base_path, &mut files);

    let mut map: BTreeMap<String, Vec<FileInfo>> = BTreeMap::new();
    for (ext, rel_path, lines, chars) in files {
        map.entry(ext).or_default().push(FileInfo { rel_path, lines, chars });
    }

    let mut total_files = 0usize;
    let mut total_lines = 0usize;
    let mut total_chars = 0u64;

    println!("=== File Tree Analysis ===\n");
    for (ext, mut infos) in map {
        infos.sort_by(|a, b| a.rel_path.cmp(&b.rel_path));
        let files_count = infos.len();
        let sum_lines: usize = infos.iter().map(|i| i.lines).sum();
        let sum_chars: u64 = infos.iter().map(|i| i.chars).sum();
        total_files += files_count;
        total_lines += sum_lines;
        total_chars += sum_chars;

        println!("Extension: {}", ext);
        println!("  Files: {}", files_count);
        println!("  Total Lines: {}", sum_lines);
        println!("  Total Characters: {}", sum_chars);
        for info in infos {
            println!("    {}: {} lines, {} chars", info.rel_path, info.lines, info.chars);
        }
    }

    println!("\nTotal: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

