    buf[len]=0;
    return buf;
}

static char *parse_number_raw(char **p){
    char *start=*p;
    while(**p && (isdigit((unsigned char)**p)||**p=='-'||**p=='+'||**p=='.'||**p=='e'||**p=='E')) (*p)++;
    size_t n=*p-start;
