JValue* parse_value(char **p){
    skip_ws(p);
    if(**p=='{') return parse_object(p);
    if(**p=='[') return parse_array(p);
    if(**p=='"'){
        char *s=parse_string_raw(p);
        JValue *v=malloc(sizeof(JValue));
        v->type=J_STRING; v->u.s=s;
        return v;
    }
    if(strncmp(*p,"true",4)==0){ *p+=4; JValue *v=malloc(sizeof(JValue)); v->type=J_BOOL; v->u.b=1; return v;}
    if(strncmp(*p,"false",5)==0){ *p+=5; JValue *v=malloc(sizeof(JValue)); v->type=J_BOOL; v->u.b=0; return v;}
    if(strncmp(*p,"null",4)==0){ *p+=4; JValue *v=malloc(sizeof(JValue)); v->type=J_NULL; return v;}
    if(isdigit((unsigned char)**p)||**p=='-'||**p=='+'){
        char *s=parse_number_raw(p);
        JValue *v=malloc(sizeof(JValue));
        v->type=J_NUMBER; v->u.s=s;
        return v;
    }
    return NULL;
}

JValue* j_copy(JValue *v){
    if(!v) return NULL;
    JValue *c=malloc(sizeof(JValue));
    c->type=v->type;
    if(v->type==J_STRING||v->type==J_NUMBER){ c->u.s=strdup(v->u.s); }
    else if(v->type==J_BOOL){ c->u.b=v->u.b; }
    else if(v->type==J_OBJECT){
        c->u.o.head=NULL;
        JPair *p=v->u.o.head, *tail=NULL;
        while(p){
            JPair *np=malloc(sizeof(JPair));
            np->key=strdup(p->key);
            np->val=j_copy(p->val);
            np->next=NULL;
            if(!c->u.o.head) c->u.o.head=np; else tail->next=np;
            tail=np; p=p->next;
        }
    }else if(v->type==J_ARRAY){
        c->u.a.head=NULL;
        JArrayItem *p=v->u.a.head, *tail=NULL;
        while(p){
            JArrayItem *ni=malloc(sizeof(JArrayItem));
            ni->val=j_copy(p->val);
            ni->next=NULL;
            if(!c->u.a.head) c->u.a.head=ni; else tail->next=ni;
            tail=ni; p=p->next;
        }
    }
    return c;
}

int j_equal(JValue *a,JValue *b){
    if(!a||!b) return a==b;
    if(a->type!=b->type) return 0;
    if(a->type==J_STRING||a->type==J_NUMBER) return strcmp(a->u.s,b->u.s)==0;
    if(a->type==J_BOOL) return a->u.b==b->u.b;
    if(a->type==J_NULL) return 1;
    if(a->type==J_ARRAY){
        JArrayItem *i=a->u.a.head,*j=b->u.a.head;
        while(i&&j){ if(!j_equal(i->val,j->val)) return 0; i=i->next; j=j->next; }
        return i==NULL && j==NULL;
    }
    if(a->type==J_OBJECT){
        JPair *i=a->u.o.head;
        while(i){ JPair *j=b->u.o.head; int found=0;
            while(j){ if(strcmp(i->key,j->key)==0){ found=1; if(!j_equal(i->val,j->val)) return 0; break;} j=j->next;}
            if(!found) return 0;
            i=i->next;
        }
        return 1;
    }
    return 0;
}

JValue* find_pair(JValue *obj,const char *key){
    if(!obj||obj->type!=J_OBJECT) return NULL;
    for(JPair *p=obj->u.o.head;p;p=p->next) if(strcmp(p->key,key)==0) return p->val;
    return NULL;
}

int key_exists(JValue *obj,const char *key){
    for(JPair *p=obj->u.o.head;p;p=p->next) if(strcmp(p->key,key)==0) return 1;
    return 0;
}

JValue* merge_values(JValue *a,JValue *b){
    if(!a) return j_copy(b);
    if(!b) return j_copy(a);
    if(a->type==J_OBJECT && b->type==J_OBJECT){
        JValue *res=malloc(sizeof(JValue));
        res->type=J_OBJECT; res->u.o.head=NULL;
        JPair **tail=&res->u.o.head;
        for(JPair *p=a->u.o.head;p;p=p->next){
            JValue *bv=find_pair(b,p->key);
            JValue *merged=bv?merge_values(p->val,bv):j_copy(p->val);
            JPair *np=malloc(sizeof(JPair));
            np->key=strdup(p->key); np->val=merged; np->next=NULL;
            *tail=np; tail=&np->next;
        }
        for(JPair *p=b->u.o.head;p;p=p->next){
            if(!key_exists(a,p->key)){
                JPair *np=malloc(sizeof(JPair));
                np->key=strdup(p->key); np->val=j_copy(p->val); np->next=NULL;
                *tail=np; tail=&np->next;
            }
        }
        return res;
    }
    if(a->type==J_ARRAY && b->type==J_ARRAY){
        JValue *res=malloc(sizeof(JValue));
        res->type=J_ARRAY; res->u.a.head=NULL;
        JArrayItem **tail=&res->u.a.head;
        for(JArrayItem *i=a->u.a.head;i;i=i->next){
            JArrayItem *ni=malloc(sizeof(JArrayItem));
            ni->val=j_copy(i->val); ni->next=NULL;
            *tail=ni; tail=&ni->next;
        }
        for(JArrayItem *i=b->u.a.head;i;i=i->next){
            int dup=0;
            for(JArrayItem *j=res->u.a.head;j;j=j->next) if(j_equal(j->val,i->val)){ dup=1; break; }
            if(!dup){
                JArrayItem *ni=malloc(sizeof(JArrayItem));
                ni->val=j_copy(i->val); ni->next=NULL;
                *tail=ni; tail=&ni->next;
            }
        }
        return res;
    }
    return j_copy(b);
}

