        else { if(!first) printf(" "); print_value(it->val,0); }
        first=0; it=it->next;
    }
    if(v->u.a.head) putchar('\n');
    print_indent(indent); putchar(']');
}
void print_value(JValue *v,int indent){
    if(!v){ printf("null"); return; }
