use std::collections::BTreeMap;
use std::fs;
use std::io::{Write, stdout};

#[derive(Debug, Clone, PartialEq)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(BTreeMap<String, JsonValue>),
}

struct Parser {
    input: Vec<u8>,
    pos: usize,
}

impl Parser {
    fn new(s: String) -> Self {
        Self { input: s.into_bytes(), pos: 0 }
    }
    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\n' | b'\r' | b'\t' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }
    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => {
                let s = self.parse_string()?;
                Ok(JsonValue::Str(s))
            }
            Some(b't') => {
                self.consume_literal(b"true")?;
                Ok(JsonValue::Bool(true))
            }
            Some(b'f') => {
                self.consume_literal(b"false")?;
                Ok(JsonValue::Bool(false))
            }
            Some(b'n') => {
                self.consume_literal(b"null")?;
                Ok(JsonValue::Null)
            }
            Some(c) if c == b'-' || c.is_ascii_digit() => {
                let n = self.parse_number()?;
                Ok(JsonValue::Number(n))
            }
            Some(c) => Err(format!("unexpected char {}", c as char)),
            None => Err("unexpected eof".into()),
        }
    }
    fn consume_literal(&mut self, lit: &[u8]) -> Result<(), String> {
        if self.input[self.pos..].starts_with(lit) {
            self.pos += lit.len();
            Ok(())
        } else {
            Err("literal mismatch".into())
        }
    }
    fn parse_string(&mut self) -> Result<String, String> {
        if self.input.get(self.pos) != Some(&b'"') {
            return Err("expected '\"'".into());
        }
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c == b'"' {
                self.pos += 1;
                return Ok(s);
            }
            if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.input.len() {
                    return Err("escape at eof".into());
                }
                let esc = self.input[self.pos];
                match esc {
                    b'"' => s.push('"'),
                    b'\\' => s.push('\\'),
                    b'/' => s.push('/'),
                    b'b' => s.push('\x08'),
                    b'f' => s.push('\x0c'),
                    b'n' => s.push('\n'),
                    b'r' => s.push('\r'),
                    b't' => s.push('\t'),
                    b'u' => {
                        if self.pos + 4 >= self.input.len() {
                            return Err("invalid \\u".into());
                        }
                        let hex = &self.input[self.pos + 1..self.pos + 5];
                        let code = u16::from_str_radix(std::str::from_utf8(hex).unwrap_or(""), 16)
                            .unwrap_or(0);
                        if let Some(ch) = char::from_u32(code as u32) {
                            s.push(ch);
                        }
                        self.pos += 4;
                    }
                    _ => s.push(esc as char),
                }
                self.pos += 1;
            } else {
                s.push(c as char);
                self.pos += 1;
            }
        }
        Err("unterminated string".into())
    }
    fn parse_number(&mut self) -> Result<f64, String> {
        let start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input[self.pos] as char;
            if c.is_ascii_digit() || "-+eE. ".contains(c) {
                self.pos += 1;
            } else {
                break;
            }
        }
        let txt = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        txt.trim()
            .parse::<f64>()
            .map_err(|e| format!("number parse error: {}", e))
    }
    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.pos += 1; // {
        self.skip_ws();
        let mut map = BTreeMap::new();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Ok(JsonValue::Object(map));
        }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.input.get(self.pos) != Some(&b':') {
                return Err("expected ':'".into());
            }
            self.pos += 1;
            let val = self.parse_value()?;
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => return Err("expected ',' or '}'".into()),
            }
        }
        Ok(JsonValue::Object(map))
    }
    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.pos += 1; // [
        self.skip_ws();
        let mut arr = Vec::new();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return Ok(JsonValue::Array(arr));
        }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => return Err("expected ',' or ']'".into()),
            }
        }
        Ok(JsonValue::Array(arr))
    }
}

fn merge_values(a: JsonValue, b: JsonValue) -> JsonValue {
    match (a, b) {
        (JsonValue::Object(mut ma), JsonValue::Object(mb)) => {
            for (k, v_b) in mb {
                if let Some(v_a) = ma.remove(&k) {
                    let merged = merge_values(v_a, v_b);
                    ma.insert(k, merged);
                } else {
                    ma.insert(k, v_b);
                }
            }
            JsonValue::Object(ma)
        }
        (JsonValue::Array(mut va), JsonValue::Array(vb)) => {
            for item in vb {
                if !va.contains(&item) {
                    va.push(item);
                }
            }
            JsonValue::Array(va)
        }
        (_, b_val) => b_val,
    }
}

fn write_indent<W: Write>(w: &mut W, indent: usize) -> std::io::Result<()> {
    for _ in 0..indent { w.write_all(b"  ")?; }
    Ok(())
}

fn escape_str(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out
}

fn write_value<W: Write>(v: &JsonValue, w: &mut W, indent: usize) -> std::io::Result<()> {
    match v {
        JsonValue::Null => w.write_all(b"null"),
        JsonValue::Bool(b) => if *b { w.write_all(b"true") } else { w.write_all(b"false") },
        JsonValue::Number(n) => {
            let s = if n.fract() == 0.0 {
                format!("{:.0}", n)
            } else {
                format!("{}", n)
            };
            w.write_all(s.as_bytes())
        }
        JsonValue::Str(s) => {
            w.write_all(b"\"")?;
            w.write_all(escape_str(s).as_bytes())?;
            w.write_all(b"\"")
        }
        JsonValue::Array(a) => write_array(a, w, indent),
        JsonValue::Object(o) => write_object(o, w, indent),
    }
}

fn write_array<W: Write>(arr: &Vec<JsonValue>, w: &mut W, indent: usize) -> std::io::Result<()> {
    if arr.is_empty() {
        return w.write_all(b"[]");
    }
    w.write_all(b"[")?;
    w.write_all(b"\n")?;
    for (i, v) in arr.iter().enumerate() {
        write_indent(w, indent + 2)?;
        write_value(v, w, indent + 2)?;
        if i + 1 < arr.len() {
            w.write_all(b",")?;
        }
        w.write_all(b"\n")?;
    }
    write_indent(w, indent)?;
    w.write_all(b"]")
}

fn write_object<W: Write>(obj: &BTreeMap<String, JsonValue>, w: &mut W, indent: usize) -> std::io::Result<()> {
    if obj.is_empty() {
        return w.write_all(b"{}");
    }
    w.write_all(b"{")?;
    w.write_all(b"\n")?;
    let mut first = true;
    for (k, v) in obj {
        if !first { w.write_all(b",\n")?; }
        first = false;
        write_indent(w, indent + 2)?;
        w.write_all(b"\"")?;
        w.write_all(escape_str(k).as_bytes())?;
        w.write_all(b"\": ")?;
        write_value(v, w, indent + 2)?;
    }
    w.write_all(b"\n")?;
    write_indent(w, indent)?;
    w.write_all(b"}")
}

fn main() {
    let path_a = "/tmp/…/config_a.json";
    let path_b = "/tmp/…/config_b.json";
    let a_str = fs::read_to_string(path_a).expect("read a");
    let b_str = fs::read_to_string(path_b).expect("read b");
    let mut p_a = Parser::new(a_str);
    let mut p_b = Parser::new(b_str);
    let v_a = p_a.parse_value().expect("parse a");
    let v_b = p_b.parse_value().expect("parse b");
    let merged = merge_values(v_a, v_b);
    let mut out = Vec::new();
    write_value(&merged, &mut out, 0).expect("write");
    stdout().write_all(&out).expect("stdout");
}

use std::collections::BTreeMap;
use std::fs;
use std::io::{Write, stdout};

#[derive(Debug, Clone, PartialEq)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(BTreeMap<String, JsonValue>),
}

struct Parser {
    input: Vec<u8>,
    pos: usize,
}

impl Parser {
    fn new(s: String) -> Self {
        Self { input: s.into_bytes(), pos: 0 }
    }
    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\n' | b'\r' | b'\t' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }
    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => {
                let s = self.parse_string()?;
                Ok(JsonValue::Str(s))
            }
            Some(b't') => {
                self.consume_literal(b"true")?;
                Ok(JsonValue::Bool(true))
            }
            Some(b'f') => {
                self.consume_literal(b"false")?;
                Ok(JsonValue::Bool(false))
            }
            Some(b'n') => {
                self.consume_literal(b"null")?;
                Ok(JsonValue::Null)
            }
            Some(c) if c == b'-' || c.is_ascii_digit() => {
                let n = self.parse_number()?;
                Ok(JsonValue::Number(n))
            }
            Some(c) => Err(format!("unexpected char {}", c as char)),
            None => Err("unexpected eof".into()),
        }
    }
    fn consume_literal(&mut self, lit: &[u8]) -> Result<(), String> {
        if self.input[self.pos..].starts_with(lit) {
            self.pos += lit.len();
            Ok(())
        } else {
            Err("literal mismatch".into())
        }
    }
    fn parse_string(&mut self) -> Result<String, String> {
        if self.input.get(self.pos) != Some(&b'"') {
            return Err("expected '\"'".into());
        }
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c == b'"' {
                self.pos += 1;
                return Ok(s);
            }
            if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.input.len() {
                    return Err("escape at eof".into());
                }
                let esc = self.input[self.pos];
                match esc {
                    b'"' => s.push('"'),
                    b'\\' => s.push('\\'),
                    b'/' => s.push('/'),
                    b'b' => s.push('\x08'),
                    b'f' => s.push('\x0c'),
                    b'n' => s.push('\n'),
                    b'r' => s.push('\r'),
                    b't' => s.push('\t'),
                    b'u' => {
                        if self.pos + 4 >= self.input.len() {
                            return Err("invalid \\u".into());
                        }
                        let hex = &self.input[self.pos + 1..self.pos + 5];
                        let code = u16::from_str_radix(std::str::from_utf8(hex).unwrap_or(""), 16)
                            .unwrap_or(0);
                        if let Some(ch) = char::from_u32(code as u32) {
                            s.push(ch);
                        }
                        self.pos += 4;
                    }
                    _ => s.push(esc as char),
                }
                self.pos += 1;
            } else {
                s.push(c as char);
                self.pos += 1;
            }
        }
        Err("unterminated string".into())
    }
    fn parse_number(&mut self) -> Result<f64, String> {
        let start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input[self.pos] as char;
            if c.is_ascii_digit() || "-+eE. ".contains(c) {
                self.pos += 1;
            } else {
                break;
            }
        }
        let txt = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        txt.trim()
            .parse::<f64>()
            .map_err(|e| format!("number parse error: {}", e))
    }
    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        self.skip_ws();
        let mut map = BTreeMap::new();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Ok(JsonValue::Object(map));
        }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.input.get(self.pos) != Some(&b':') {
                return Err("expected ':'".into());
            }
            self.pos += 1;
            let val = self.parse_value()?;
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => return Err("expected ',' or '}'".into()),
            }
        }
        Ok(JsonValue::Object(map))
    }
    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        self.skip_ws();
        let mut arr = Vec::new();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return Ok(JsonValue::Array(arr));
        }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => return Err("expected ',' or ']'".into()),
            }
        }
        Ok(JsonValue::Array(arr))
    }
}

fn merge_values(a: JsonValue, b: JsonValue) -> JsonValue {
    match (a, b) {
        (JsonValue::Object(mut ma), JsonValue::Object(mb)) => {
            for (k, v_b) in mb {
                if let Some(v_a) = ma.remove(&k) {
                    let merged = merge_values(v_a, v_b);
                    ma.insert(k, merged);
                } else {
                    ma.insert(k, v_b);
                }
            }
            JsonValue::Object(ma)
        }
        (JsonValue::Array(mut va), JsonValue::Array(vb)) => {
            for item in vb {
                if !va.contains(&item) {
                    va.push(item);
                }
            }
            JsonValue::Array(va)
        }
        (_, b_val) => b_val,
    }
}

fn write_indent<W: Write>(w: &mut W, indent: usize) -> std::io::Result<()> {
    for _ in 0..indent { w.write_all(b" ")?; }
    Ok(())
}

fn escape_str(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out
}

fn write_value<W: Write>(v: &JsonValue, w: &mut W, indent: usize) -> std::io::Result<()> {
    match v {
        JsonValue::Null => w.write_all(b"null"),
        JsonValue::Bool(b) => if *b { w.write_all(b"true") } else { w.write_all(b"false") },
        JsonValue::Number(n) => {
            let s = if n.fract() == 0.0 {
                format!("{:.0}", n)
            } else {
                format!("{}", n)
            };
            w.write_all(s.as_bytes())
        }
        JsonValue::Str(s) => {
            w.write_all(b"\"")?;
            w.write_all(escape_str(s).as_bytes())?;
            w.write_all(b"\"")
        }
        JsonValue::Array(a) => write_array(a, w, indent),
        JsonValue::Object(o) => write_object(o, w, indent),
    }
}

fn write_array<W: Write>(arr: &Vec<JsonValue>, w: &mut W, indent: usize) -> std::io::Result<()> {
    if arr.is_empty() {
        return w.write_all(b"[]");
    }
    w.write_all(b"[")?;
    w.write_all(b"\n")?;
    for (i, v) in arr.iter().enumerate() {
        write_indent(w, indent + 2)?;
        write_value(v, w, indent + 2)?;
        if i + 1 < arr.len() {
            w.write_all(b",")?;
        }
        w.write_all(b"\n")?;
    }
    write_indent(w, indent)?;
    w.write_all(b"]")
}

fn write_object<W: Write>(obj: &BTreeMap<String, JsonValue>, w: &mut W, indent: usize) -> std::io::Result<()> {
    if obj.is_empty() {
        return w.write_all(b"{}");
    }
    w.write_all(b"{")?;
    w.write_all(b"\n")?;
    let mut first = true;
    for (k, v) in obj {
        if !first { w.write_all(b",\n")?; }
        first = false;
        write_indent(w, indent + 2)?;
        w.write_all(b"\"")?;
        w.write_all(escape_str(k).as_bytes())?;
        w.write_all(b"\": ")?;
        write_value(v, w, indent + 2)?;
    }
    w.write_all(b"\n")?;
    write_indent(w, indent)?;
    w.write_all(b"}")
}

fn main() {
    let path_a = "/tmp/…/config_a.json";
    let path_b = "/tmp/…/config_b.json";
    let a_str = fs::read_to_string(path_a).expect("read a");
    let b_str = fs::read_to_string(path_b).expect("read b");
    let mut p_a = Parser::new(a_str);
    let mut p_b = Parser::new(b_str);
    let v_a = p_a.parse_value().expect("parse a");
    let v_b = p_b.parse_value().expect("parse b");
    let merged = merge_values(v_a, v_b);
    let mut out = Vec::new();
    write_value(&merged, &mut out, 0).expect("write");
    stdout().write_all(&out).expect("stdout");
}
